'use strict';

const BbPromise = require('bluebird');
const path = require('path');
const mergeCustomProviderResources = require('./lib/mergeCustomProviderResources');
const generateArtifactDirectoryName = require('./lib/generateArtifactDirectoryName');
const generateCoreTemplate = require('./lib/generateCoreTemplate');
const saveServiceState = require('./lib/saveServiceState');
const saveCompiledTemplate = require('./lib/saveCompiledTemplate');
const mergeIamTemplates = require('./lib/mergeIamTemplates');

class AwsPackage {
  constructor(serverless, options) {
    this.serverless = serverless;
    this.options = options;
    this.servicePath = this.serverless.config.servicePath || '';
    this.packagePath = this.options.package ||
      this.serverless.service.package.path ||
      path.join(this.servicePath || '.', '.serverless');
    this.provider = this.serverless.getProvider('aws');

    Object.assign(
      this,
      generateCoreTemplate,
      mergeIamTemplates,
      generateArtifactDirectoryName,
      mergeCustomProviderResources,
      saveServiceState,
      saveCompiledTemplate
    );

    // Define inner lifecycles
    this.commands = {
      aws: {
        type: 'entrypoint',
        commands: {
          package: {
            commands: {
              finalize: {
                lifecycleEvents: [
                  'mergeCustomProviderResources',
                  'saveServiceState',
                ],
              },
            },
          },
        },
      },
    };

    this.hooks = {
      /**
       * Outer lifecycle hooks
       */
      'package:cleanup': () => BbPromise.bind(this)
        .then(() => this.serverless.pluginManager.spawn('aws:common:validate'))
        .then(() => this.serverless.pluginManager.spawn('aws:common:cleanupTempDir')),

      'package:initialize': () => BbPromise.bind(this)
        .then(this.generateCoreTemplate),

      'package:setupProviderConfiguration': () => BbPromise.bind(this)
        .then(this.mergeIamTemplates),

      'before:package:compileFunctions': () => BbPromise.bind(this)
        .then(this.generateArtifactDirectoryName),

      'before:package:compileLayers': () => BbPromise.bind(this)
        .then(this.generateArtifactDirectoryName),

      'package:finalize': () => BbPromise.bind(this)
        .then(() => this.serverless.pluginManager.spawn('aws:package:finalize')),

      /**
       * Inner lifecycle hooks
       */

      // Package finalize inner lifecycle
      'aws:package:finalize:mergeCustomProviderResources': () => BbPromise.bind(this)
        .then(this.mergeCustomProviderResources),

      'aws:package:finalize:saveServiceState': () => BbPromise.bind(this)
        .then(this.saveCompiledTemplate)
        .then(this.saveServiceState)
        .then(() => this.serverless.pluginManager.spawn('aws:common:moveArtifactsToPackage')),
    };
  }
}

module.exports = AwsPackage;

'use strict';

const path = require('path');
const expect = require('chai').expect;
const AwsPackage = require('../index');
const Serverless = require('../../../../Serverless');

describe('mergeCustomProviderResources', () => {
  let serverless;
  let awsPackage;
  let coreCloudFormationTemplate;

  beforeEach(() => {
    serverless = new Serverless();
    awsPackage = new AwsPackage(serverless, {});

    coreCloudFormationTemplate = awsPackage
      .serverless.utils.readFileSync(
        path.join(
          __dirname,
          '..',
          'lib',
          'core-cloudformation-template.json'
        )
      );

    awsPackage.serverless.service.provider
      .compiledCloudFormationTemplate = coreCloudFormationTemplate;
  });

  describe('#mergeCustomProviderResources()', () => {
    it('should set an empty resources.Resources object if it is not present', () => {
      awsPackage.serverless.service.provider
        .compiledCloudFormationTemplate.Resources = {}; // reset the core CloudFormation template
      awsPackage.serverless.service.resources.Resources = null;

      return awsPackage.mergeCustomProviderResources().then(() => {
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate.Resources)
          .to.deep.equal({});
      });
    });

    it('should set an empty resources.Outputs object if it is not present', () => {
      awsPackage.serverless.service.provider
        .compiledCloudFormationTemplate.Outputs = {}; // reset the core CloudFormation template
      awsPackage.serverless.service.resources.Outputs = null;

      return awsPackage.mergeCustomProviderResources().then(() => {
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate.Outputs)
          .to.deep.equal({});
      });
    });

    it('should be able to overwrite existing string properties', () => {
      const customResourcesMock = {
        Description: 'Some shiny new description',
      };

      awsPackage.serverless.service.resources = customResourcesMock;

      return awsPackage.mergeCustomProviderResources().then(() => {
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate.Description)
          .to.equal(customResourcesMock.Description);
      });
    });

    it('should be able to overwrite existing object properties', () => {
      const customResourcesMock = {
        Resources: {
          ServerlessDeploymentBucket: {
            Type: 'Some::New::Type',
            FakeResource1: 'FakePropValue',
            FakeResource2: {
              FakePropKey: 'FakePropValue',
            },
            Properties: {
              BucketEncryption: {
                ServerSideEncryptionConfiguration: [
                  {
                    ServerSideEncryptionByDefault: {
                      SSEAlgorithm: 'AES256',
                    },
                  },
                ],
              },
            },
          },
        },
      };

      awsPackage.serverless.service.resources = customResourcesMock;

      return awsPackage.mergeCustomProviderResources().then(() => {
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .Resources.ServerlessDeploymentBucket
        ).to.deep.equal(customResourcesMock.Resources.ServerlessDeploymentBucket);
      });
    });

    it('should be able to merge in new object property definitions', () => {
      // make sure that the promise will resolve
      const customResourcesMock = {
        Resources: {
          FakeResource1: {
            FakePropKey: 'FakePropValue',
          },
          FakeResource2: {
            FakePropKey: 'FakePropValue',
          },
        },
        Outputs: {
          FakeOutput1: {
            Value: 'FakeValue',
          },
          FakeOutput2: {
            Value: 'FakeValue',
          },
        },
        CustomDefinition: {
          Foo: 'Bar',
        },
      };

      awsPackage.serverless.service.resources = customResourcesMock;

      return awsPackage.mergeCustomProviderResources().then(() => {
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .Resources.FakeResource1).to.deep.equal(customResourcesMock.Resources.FakeResource1);
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .Resources.FakeResource2).to.deep.equal(customResourcesMock.Resources.FakeResource2);
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .Outputs.FakeOutput1).to.deep.equal(customResourcesMock.Outputs.FakeOutput1);
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .Outputs.FakeOutput2).to.deep.equal(customResourcesMock.Outputs.FakeOutput2);
        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .CustomDefinition).to.deep.equal(customResourcesMock.CustomDefinition);
      });
    });

    it('should keep the core template definitions when merging custom resources', () => {
      const customResourcesMock = {
        NewStringProp: 'New string prop',
        NewObjectProp: {
          newObjectPropKey: 'New object prop value',
        },
      };

      awsPackage.serverless.service.resources = customResourcesMock;

      return awsPackage.mergeCustomProviderResources().then(() => {
        expect(
          awsPackage.serverless.service.provider.compiledCloudFormationTemplate
            .AWSTemplateFormatVersion
        ).to.equal(
          coreCloudFormationTemplate.AWSTemplateFormatVersion
        );

        expect(
          awsPackage.serverless.service.provider.compiledCloudFormationTemplate.Description
        ).to.equal(
          coreCloudFormationTemplate.Description
        );

        expect(awsPackage.serverless.service.provider.compiledCloudFormationTemplate
          .Resources.ServerlessDeploymentBucket
        ).to.deep.equal(
          coreCloudFormationTemplate.Resources.ServerlessDeploymentBucket
        );

        expect(
          awsPackage.serverless.service.provider.compiledCloudFormationTemplate
            .Outputs.ServerlessDeploymentBucketName
        ).to.deep.equal(
          coreCloudFormationTemplate.Outputs.ServerlessDeploymentBucketName
        );
      });
    });
  });
});

'use strict';

const _ = require('lodash');
const BbPromise = require('bluebird');

module.exports = {
  mergeCustomProviderResources() {
    if (this.serverless.service.resources && !this.serverless.service.resources.Resources) {
      this.serverless.service.resources.Resources = {};
    }
    if (this.serverless.service.resources && !this.serverless.service.resources.Outputs) {
      this.serverless.service.resources.Outputs = {};
    }

    _.merge(
      this.serverless.service.provider.compiledCloudFormationTemplate,
      this.serverless.service.resources
    );

    return BbPromise.resolve();
  },
};

'use strict';

const _ = require('lodash');
const BbPromise = require('bluebird');

module.exports = {
  compileDeployment() {
    this.apiGatewayDeploymentLogicalId = this.provider.naming
      .generateApiGatewayDeploymentLogicalId();

    _.merge(this.serverless.service.provider.compiledCloudFormationTemplate.Resources, {
      [this.apiGatewayDeploymentLogicalId]: {
        Type: 'AWS::ApiGateway::Deployment',
        Properties: {
          RestApiId: this.provider.getApiGatewayRestApiId(),
          StageName: this.provider.getStage(),
          Description: this.provider.getApiGatewayDescription(),
        },
        DependsOn: this.apiGatewayMethodLogicalIds,
      },
    });

    // create CLF Output for endpoint
    _.merge(this.serverless.service.provider.compiledCloudFormationTemplate.Outputs, {
      ServiceEndpoint: {
        Description: 'URL of the service endpoint',
        Value: {
          'Fn::Join': ['',
            [
              'https://',
              this.provider.getApiGatewayRestApiId(),
              `.execute-api.${this.provider.getRegion()}.`,
              { Ref: 'AWS::URLSuffix' },
              `/${this.provider.getStage()}`,
            ],
          ],
        },
      },
    });
    return BbPromise.resolve();
  },
};

// Public verification helper: its defaults come only from the original checkout.
const fs=require('fs'),path=require('path'),{spawnSync}=require('child_process');
const root=process.cwd(),config=JSON.parse(fs.readFileSync('verification.json','utf8')),args=process.argv.slice(2);
const value=name=>{const index=args.indexOf(name);return index<0?undefined:args[index+1];};
const report=path.resolve(value('--report')||'.v4-tmp/public-report.json');fs.mkdirSync(path.dirname(report),{recursive:true});
const selected=value('--tests-json'),tests=selected?JSON.parse(fs.readFileSync(selected,'utf8')):config.publicTests;
const env={...process.env,CI:'true',TZ:'UTC',NODE_ENV:'test',NODE_OPTIONS:'--max-old-space-size=384',SUFFICE_EVAL_REPORT:report};
const execute=(argv,timeout=240000)=>spawnSync(config.nodeRuntime,['--max-old-space-size=384',...argv],{cwd:root,env,encoding:'utf8',windowsHide:true,timeout,maxBuffer:16*1024**2});
for(const build of config.buildSteps){
  const result=execute(build,120000);if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);
  if(result.status!==0){fs.writeFileSync(report,JSON.stringify({framework:config.framework,executionFailure:{stage:'build',code:result.status,signal:result.signal,error:result.error?.message,launchErrorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}}));process.exit(result.status||1);}
}
let invocation;
if(config.framework==='mocha')invocation=['node_modules/mocha/bin/_mocha',...(config.mochaRequires??[]).flatMap(name=>['--require',name]),...tests,'--reporter',path.resolve('.v4-mocha-reporter.cjs'),'--timeout','15000','--exit'];
else if(config.framework==='jest')invocation=['node_modules/jest/bin/jest.js','--runInBand','--watchman=false','--json','--outputFile',report,'--no-cache','--runTestsByPath',...tests];
else if(config.framework==='qunit')invocation=['.v4-qunit-runner.cjs',config.qunitEntry];
else throw new Error('Unknown verified framework');
const result=execute(invocation);if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);
if(!fs.existsSync(report))fs.writeFileSync(report,JSON.stringify({framework:config.framework,executionFailure:{stage:'test',code:result.status,signal:result.signal,error:result.error?.message,launchErrorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}}));
if(result.error)process.stderr.write('\n'+result.error.message+'\n');
console.log('\nVerification report: '+path.relative(root,report));process.exit(result.status??1);

